/**
 * ARV approval ledger note parser -- test runner. B8-07 / INV-50, Jess
 * Gate correction.
 *
 * Compiles arv-approval-note.ts alongside the REAL arv-persist.ts (the
 * writer this module is the strict inverse of) and its dependencies, so
 * fixtures are generated by the actual `formatArvApprovalNote` function --
 * not a hand-typed guess at its format. No GHL, no network.
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const APP = path.resolve(__dirname, '..');
const TMP = path.join(APP, '.tmp-arv-approval-note-test');
const LIB = path.join(APP, 'src', 'lib');

function cleanup() {
  try { fs.rmSync(TMP, { recursive: true, force: true }); } catch (e) {}
}

cleanup();
fs.mkdirSync(TMP, { recursive: true });
fs.writeFileSync(path.join(TMP, 'package.json'), JSON.stringify({ type: 'commonjs' }), 'utf8');

const SOURCES = [
  path.join(LIB, 'arv-reconciliation.ts'),
  path.join(LIB, 'comp-classification.ts'),
  path.join(LIB, 'propstream-comp-csv.ts'),
  path.join(LIB, 'arv-persist.ts'),
  path.join(LIB, 'arv-approval-note.ts'),
];

try {
  execSync(
    'npx tsc ' + SOURCES.map((s) => '"' + s + '"').join(' ') +
    ' --outDir "' + TMP + '" --module commonjs --target es2020 --strict',
    { cwd: APP, stdio: 'inherit' }
  );
} catch (e) {
  console.error('ABORT: TypeScript compilation failed. Nothing tested.');
  cleanup();
  process.exit(10);
}

const persistPath = path.join(TMP, 'arv-persist.js');
const parserPath = path.join(TMP, 'arv-approval-note.js');
for (const p of [persistPath, parserPath]) {
  if (!fs.existsSync(p)) {
    console.error('ABORT: expected compiled output at ' + p);
    cleanup();
    process.exit(11);
  }
}

const { formatArvApprovalNote, ARV_APPROVAL_LEDGER_VERSION } = require(persistPath);
const { parseArvApprovalNote, latestArvApprovalForOpportunity } = require(parserPath);

/** Literal call-site count taken from the finished file, never back-filled from a passing run. */
const FLOOR = 25;
let failures = 0;
let checks = 0;

function check(name, actual, expected) {
  checks++;
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (ok) {
    console.log('PASS  ' + name);
  } else {
    failures++;
    console.error('FAIL  ' + name);
    console.error('      expected: ' + JSON.stringify(expected));
    console.error('      actual:   ' + JSON.stringify(actual));
  }
}

function realApprovedNote(over) {
  const approval = Object.assign({ kind: 'approved', amount: 250000, recommendedArv: 250000, revision: 1 }, over && over.approval);
  const provenance = Object.assign({
    approvedAt: '2026-09-04T20:00:00.000Z',
    operator: 'Brad Thompson',
    opportunityId: 'opp-test-1',
    evidenceState: 'HIGH',
    reconciliationOutcome: 'RECOMMENDED',
    acceptedCompCount: 4,
    searchLevel: 'STANDARD',
    source: { kind: 'propstream_csv', version: 'propstream-comparable-csv-v1', fileName: 'test-comps.csv', importedAt: '2026-09-04T19:00:00.000Z' },
  }, over && over.provenance);
  return formatArvApprovalNote(approval, provenance);
}

// ============================================================
// Round-trip fidelity: a note produced by the REAL writer parses back to
// exactly what was written.
// ============================================================
{
  const note = realApprovedNote();
  const parsed = parseArvApprovalNote(note);
  check('round-trip: parses a real formatArvApprovalNote note', parsed !== null, true);
  check('round-trip: opportunityId matches', parsed.opportunityId, 'opp-test-1');
  check('round-trip: evidenceState matches', parsed.evidenceState, 'HIGH');
  check('round-trip: decision APPROVED matches', parsed.decision, 'APPROVED');
  check('round-trip: approvedAt matches', parsed.approvedAt, '2026-09-04T20:00:00.000Z');
}

// ============================================================
// OVERRIDE decision still yields its evidence state -- the human action
// is separate from the evidence classification (B8-04's own principle).
// ============================================================
{
  const note = realApprovedNote({ approval: { kind: 'overridden', amount: 260000, recommendedArv: 250000, revision: 2 }, provenance: { evidenceState: 'LOW' } });
  const parsed = parseArvApprovalNote(note);
  check('override note parses', parsed !== null, true);
  check('override note decision is OVERRIDE', parsed.decision, 'OVERRIDE');
  check('override note still carries its evidence state (LOW)', parsed.evidenceState, 'LOW');
}

// ============================================================
// Every evidence state round-trips correctly.
// ============================================================
{
  for (const state of ['HIGH', 'MODERATE', 'LOW', 'INSUFFICIENT']) {
    const parsed = parseArvApprovalNote(realApprovedNote({ provenance: { evidenceState: state } }));
    check('evidence state ' + state + ' round-trips exactly', parsed.evidenceState, state);
  }
}

// ============================================================
// Fails closed: malformed / wrong-version / non-ledger notes never parse.
// ============================================================
{
  check('a plain call note is not mistaken for a ledger note', parseArvApprovalNote('Called seller, left voicemail.'), null);
  check('an empty body is not mistaken for a ledger note', parseArvApprovalNote(''), null);

  const wrongVersion = realApprovedNote().replace(ARV_APPROVAL_LEDGER_VERSION, 'iaos-arv-approval-v2-future');
  check('a note claiming a DIFFERENT ledger version is refused, not guessed', parseArvApprovalNote(wrongVersion), null);

  const truncated = realApprovedNote().split('\n').slice(0, 3).join('\n');
  check('a truncated note (missing required fields) is refused', parseArvApprovalNote(truncated), null);

  const badEvidence = realApprovedNote().replace('Evidence state: HIGH', 'Evidence state: PRETTY GOOD');
  check('an evidence-state value outside the four locked states is refused', parseArvApprovalNote(badEvidence), null);

  check('parseArvApprovalNote never throws on a non-string body', (() => { try { parseArvApprovalNote(null); return true; } catch { return false; } })(), true);
}

// ============================================================
// latestArvApprovalForOpportunity: picks the CURRENT standing entry by
// the note's OWN embedded timestamp, matches only the given opportunity,
// and silently skips unrelated notes.
// ============================================================
{
  const older = realApprovedNote({ provenance: { approvedAt: '2026-09-01T10:00:00.000Z', evidenceState: 'LOW' } });
  const newer = realApprovedNote({ provenance: { approvedAt: '2026-09-04T20:00:00.000Z', evidenceState: 'HIGH' } });
  const otherOpportunity = realApprovedNote({ provenance: { opportunityId: 'a-different-opportunity', approvedAt: '2026-09-05T00:00:00.000Z', evidenceState: 'INSUFFICIENT' } });
  const unrelatedCallNote = { body: 'Called seller, left voicemail.' };

  // Deliberately out of chronological order, to prove sort-by-embedded-
  // timestamp rather than list order.
  const notes = [{ body: newer }, unrelatedCallNote, { body: older }, { body: otherOpportunity }];

  const latest = latestArvApprovalForOpportunity(notes, 'opp-test-1');
  check('latest entry picked is the CHRONOLOGICALLY latest, not the first in the list', latest.evidenceState, 'HIGH');
  check('latest entry ignores a different opportunity\'s ledger note', latest.opportunityId, 'opp-test-1');

  const noneForThisOpportunity = latestArvApprovalForOpportunity([{ body: otherOpportunity }, unrelatedCallNote], 'opp-test-1');
  check('no matching ledger note for this opportunity -> null, never a guess', noneForThisOpportunity, null);

  const emptyList = latestArvApprovalForOpportunity([], 'opp-test-1');
  check('empty note list -> null', emptyList, null);
}

// ============================================================
// Structural proof: no second economics/ARV engine, no GHL call, no
// duplicated ARV_APPROVAL_LEDGER_VERSION constant.
// ============================================================
{
  const src = fs.readFileSync(path.join(LIB, 'arv-approval-note.ts'), 'utf8');
  check('source imports ARV_APPROVAL_LEDGER_VERSION from arv-persist.ts rather than duplicating it', /import\s*\{\s*ARV_APPROVAL_LEDGER_VERSION\s*\}\s*from\s*"\.\/arv-persist"/.test(src), true);
  // Checked against compiled output (comments stripped) rather than source
  // text: the module's OWN header comment discusses `ghl.notes.list` as
  // context for why this module is safe, which would false-positive a
  // plain source-text substring/regex check (same class of mistake as the
  // earlier next-best-question.ts and 0.25-in-CSS false positives this
  // session).
  const compiledNoComments = execSync(
    'npx tsc "' + path.join(LIB, 'arv-approval-note.ts') + '" --outDir "' + TMP + '-nocomments" --module commonjs --target es2020 --removeComments',
    { cwd: APP }
  ) && fs.readFileSync(path.join(TMP + '-nocomments', 'arv-approval-note.js'), 'utf8');
  fs.rmSync(TMP + '-nocomments', { recursive: true, force: true });
  check('compiled output (comments stripped) makes no GHL/network call', !/fetch\(|ghl\.|XMLHttpRequest/.test(compiledNoComments), true);
  check('compiled output never derives evidence from an ARV dollar amount', !/arv_after_repair_value|approvedArv|\.amount\b/.test(compiledNoComments), true);
}

cleanup();

console.log('');
console.log('checksRun=' + checks + ' failures=' + failures + ' floor=' + FLOOR);
if (checks !== FLOOR) {
  console.error('FAILED: expected exactly ' + FLOOR + ' checks, ran ' + checks + '. A case was added or removed without updating FLOOR.');
  process.exit(2);
}
if (failures > 0) {
  console.error('FAILED');
  process.exit(1);
}
console.log('OK');
